import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    A = int(input_data[0])
    B = int(input_data[1])

    SA = input_data[2:2 + A]
    SB = input_data[2 + A:2 + A + B]

    ptr_B = 0
    for x in SA:
        if x == SB[ptr_B]:
